INSERT INTO `groups` VALUES (1,'art4soul','password','Will Johns','manager@millhouse.org.au','54613185','Art for the Soul',3,5,0,'0000-01-01 10:00:00','0000-01-01 10:00:00',2.00,0.00,000,1,'A relaxed and welcoming space where people of all skills can create learn and enjoy conversation with our Artist in residence Will.','https://www.instagram.com/willjohns26/',0,1,1),(5,'dungeons_dragons','password','Tristan & Charlotte','manager@millhouse.org.au','54613185','Dungeons & Dragons',2,-1,0,'0000-01-01 09:00:00','0000-01-01 13:00:00',3.00,0.00,000,1,' Beginners: 9AM to 1PM, All: 1PM to 4PM (causal). This a casual group is for anyone that enjoys playing table top games, including dungeons & dragons.',NULL,0,1,1),(7,'playgroup','password','Sarah Mclean','sarahmc@djerriwarrh.org','0422629249','Millhouse Playgroup',3,3,0,'0000-01-01 10:30:00','0000-01-01 11:00:00',2.00,0.00,000,0,'A relaxed child led space where young children and their care givers connect, explore and learn through play together.',NULL,0,1,1),(8,'parent_pathways1','password','Sarah McLean','manager@millhouse.org.au','0422629249','Parent Pathways',1,3,0,'0000-01-01 09:00:00',NULL,7.00,0.00,000,0,'By appointment. This group allows parents select appropriate Service Australia support programs, with the help of a mentor.',NULL,0,1,1),(9,'u3a_writers','password','Val Dwyer or Maria Lacey','manager@millhouse.org.au','54613185','U3A Writers Group',5,-1,1,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,' Members take turns leading the sessions and choosing topics, with no minimum or maximum word limits.',NULL,0,1,1),(10,'u3a_photobooks','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Digital Photobooks',2,-1,0,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'U3A Maryborough group creating digital stories through images and photobooks.',NULL,0,1,1),(12,'u3a_books','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Book Club',2,-1,2,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'A group of like-minded seniors enjoying reading and sharing books.','',0,1,1),(14,'stamps','password','Grey Loyer','manager@millhouse.org.au','0354605008','Stamp Club',2,-1,2,'0000-01-01 20:00:00',NULL,2.00,0.00,000,1,'This group is for anyone with a passion for collecting coins and stamps. We can assist you with valuation of your collection. You can buy, sell & swap. We hold auctions and an annual fair.','',0,1,1),(15,'scrappers','password','Sarah MacLean','manager@millhouse.org.au','54613185','Millhouse Scrappers',2,-1,0,'0000-01-01 10:00:00',NULL,2.00,0.00,001,1,'A creative group preserving memories combining photos, keepsakes, and storytelling on decorated pages.','',0,1,1),(16,'cafe','password','Sarah','manager@millhouse.org.au','54613185','Millhouse Cafe',2,-1,0,'0000-01-01 11:00:00',NULL,2.00,5.00,000,0,'A relaxed and welcoming social café, offering a small affordable menu including a barista coffee and cake for $5.00. Come in for a cuppa and connect with others from the community.','',0,1,1),(17,'feast','password','Sarah','manager@millhouse.org.au','54613185','Friday Feast',5,-1,0,'0000-01-01 12:00:00',NULL,2.00,5.00,001,0,'A freshly prepared community meal. Good food in a friendly social setting.','',0,1,1),(20,'market','password','Sarah','manager@millhouse.org.au','54613185','Millhouse Market',4,-1,0,'0000-01-01 09:30:00',NULL,2.00,5.00,001,0,'For a small donation attendees can take home a basket full of grocery items.','',0,1,1),(21,'food_friends','password','Sarah McLean','manager@millhouse.org.au','54613185','Food with Friends',4,-1,0,'0000-01-01 10:00:00',NULL,2.00,10.00,000,0,'Only run during school terms. A supported cooking group for all-abilities and their carers’. Make some lunch and eat.','',0,1,1),(22,'labour_party','password','Secretary','secretary@maryboroughlabor.com','54613185','Australian Labour Party',2,-1,2,'0000-01-01 19:00:00',NULL,2.00,0.00,000,0,'Meeting of the local Labour Party membership.','https://www.facebook.com/maryboroughlabor/',0,1,1),(23,'theatre','password','Sarah McLean','maryborough.theatre.company@gmail.com','54613185','Maryborough Theatre Company',2,-1,4,'0000-01-01 19:00:00',NULL,2.00,0.00,000,0,'Maryborough Theatre Company provides a total theatre experience for all children and adults.','https://www.facebook.com/MaryboroughTheatreCompany/directory_intro',0,1,1),(24,'admin','password','Sarah McLean','manager@millhouse.org.au','0422629249','Administrator',-1,-1,-1,NULL,NULL,0.00,0.00,000,0,'Just to store the admin password.','',0,1,1),(25,'yarn','password','Sarah McLean, Rhonda or Ruth','manager@millhouse.org.au','0000000000','Yarn Craft Group - ‘The Hookers’',5,-1,0,'0000-01-01 13:00:00',NULL,2.00,0.00,000,1,'A friendly safe space to learn and practice yarn crafts with a group of crafty ladies.','',1,1,1),(27,'gamers','password','Chris Lakey',' chris.lakey@lifely.org.au ','0427 716 308','Level Up Youth Gaming',2,-1,0,'0000-01-01 15:30:00',NULL,2.00,0.00,000,1,'A weekly after-school social and gaming group designed for kids and teens aged 9 to 17 who experience disability or neuro-divergence. The program focuses on building friendships, improving focus, and boosting confidence in a safe, supportive environment.','',0,1,1),(28,'axis_employment','password','Joel & Jack','reception@caei.com.au','1800 811 622','Axis Emplyment',2,4,0,'0000-01-01 09:00:00',NULL,7.00,0.00,000,0,'At CAEI, we believe employment is more than a job - it is a pathway to independence, connection, and wellbeing.','https://www.facebook.com/axisemployment.caei/',0,1,1),(29,'are-able','password','Dianne Pin','samhallam@areable.org.au','1800 566 066','are-able Employment',-1,-1,0,'0000-01-01 09:00:00',NULL,8.00,0.00,000,0,'Do you have an illness, injury or disability? We’ll work with you, at your own pace, to help find a job you love.','https://www.facebook.com/areable.community',0,1,1),(30,'connecting_futures','password','Wayne Kelly','wayne@connectingfutures.com.au','0408493060','Conncting Futures',3,-1,0,'0000-01-01 10:00:00',NULL,6.00,0.00,000,0,'We work with NDIS participants via the School Leavers Employment Support service in to help them prepare for and find work opportunities. Our services are focused on a holistic approach, meaning we help build soft skills, technical skills and work with other professionals involved in supporting you towards your goals.','https://www.facebook.com/ConnectingFuturesLM/',0,1,1),(31,'apm','password','Wayne','apm4jobs@apm.net.au','1800 276 276','APM Employment Services',3,5,0,'0000-01-01 09:00:00',NULL,7.00,0.00,000,0,'By appointment. Our purpose is enabling better lives. Our mission is to help people become more independent, feel like they belong, and get involved in their communities. With a team of over 16,000 caring professionals, we’re dedicated to this cause.','https://www.facebook.com/APMAustralia/',0,1,1),(32,'massage','password','Neil Smyth','manager@millhouse.org.au','0436287447','Remedial Massage',-1,-1,-1,'0000-01-01 09:00:00',NULL,10.00,0.00,000,0,'By appointment. Remedial Massage Therapist  provides services at Mill House. Appointment and fees are arranged directly with Neil the practitioner.','https://www.facebook.com/maryboroughrsm/',0,1,1),(33,'canasta','password','Jen Fisher','manager@millhouse.org.au','54613185','Canasta',5,-1,-1,'0000-01-01 13:00:00',NULL,3.00,0.00,000,1,'For anyone who wants to enjoy a social game of canasta.',NULL,0,1,1),(34,'peer_collective','password','Jen','manager@millhouse.org.au','54613185','Peer Collective Support Group',3,-1,0,'0000-01-01 14:00:00',NULL,2.00,0.00,000,1,'A friendly group meeting for a cuppa, a chat and mutual support. All welcome.',NULL,0,1,1),(36,'justice_peace','password','Terry Simpson','manager@millhouse.org.au','0419737837','Justice of the Peace',2,-1,0,'0000-01-01 10:00:00',NULL,4.00,0.00,000,1,'JP Terry Simpson available for people who need documents witnessed or certified. By appointments appreciated but not necessary.','https://www.rvahj.org.au/find-a-justice-of-the-peace/?wcm_dir_plan=39983%2C35030%2C16655%2C16653&wcm_dir_status=wcm-active&wcm_dir_search=maryborough',0,1,1),(37,'youth_hub','password','Sarah MacLean','manager@millhouse.org.au','54613185','The ‘House’ Youth Activity Hub',3,-1,0,'0000-01-01 15:30:00',NULL,1.50,0.00,000,1,'Only run during school terms. A welcoming space for young people to meet, play games and participate in activities, develop new skills and connect with others.',NULL,0,1,1),(38,'maker_mums','password','Sarah MacLean','manager@millhouse.org.au','54613185','Maker Mums',1,-1,0,'0000-01-01 12:15:00',NULL,1.75,0.00,000,1,'A welcoming creative and social group where parents can connect, work on sewing, craft and other projects, and share skills in a child-friendly environment.',NULL,0,1,1),(40,'parent_pathways2','password','Samantha Redlich','manager@millhouse.org.au','54613185','Parent Pathways',2,4,0,'0000-01-01 09:00:00',NULL,7.00,0.00,000,1,'By appointment. This group allows parents select appropriate Service Australia support programs, with the help of a mentor.',NULL,0,1,1);
